SELECT json_object('obs','doc-text','declined',CASE WHEN (SELECT doc_text FROM documents WHERE doc_id=1) IS NULL THEN 1 ELSE 0 END,'value_kind','text','value',(SELECT doc_text FROM documents WHERE doc_id=1),'coord',json_object('format',(SELECT format FROM documents WHERE doc_id=1),'kind','document','ordinal',NULL),'provenance',NULL,'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)